                h: "Where and how to use it",
                p: "Our water retainers are used in conventional and organic farming alike — they actually speed up the transition to certified organic — as well as in arboriculture, nurseries, landscaping and agroforestry. Over 95% of transplanted trees survive; remaining losses come from non-viable plants or wildlife damage, never from water stress. Golf courses and municipalities that adopt them report watering labour savings large enough, from the very first season, to cover the cost of the product. Simply mix them into the planting substrate; they are compatible with fertilisers, biostimulants or bacteria, whose action is enhanced by the constant presence of water.",
